"""Ceiling in a Sorted Array — lower bound.

Time: O(log n)   Space: O(1)
"""
from typing import List


class Solution:
    def findCeil(self, nums: List[int], x: int) -> int:
        lo, hi, answer = 0, len(nums) - 1, -1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] >= x:
                answer = nums[mid]
                hi = mid - 1
            else:
                lo = mid + 1
        return answer
